import re


def bulk_discount(qty):
    if qty >= 50:
        return 0.12
    if qty >= 10:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


_SKU_RE = re.compile(r"^([A-Z]{2,4}):([0-9]{4}):([A-Za-z])$")


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError("SKU must be a string")
    m = _SKU_RE.match(s)
    if not m:
        raise ValueError(f"invalid SKU: {s!r}")
    category, number, variant = m.group(1), m.group(2), m.group(3)
    return {"category": category, "number": int(number), "variant": variant}

"""Shipping helpers for task D2."""

_BASE_BY_ZONE = {1: 5.0, 2: 12.0, 3: 25.0}


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    1 for US, 2 for CA or MX, 3 for any other code.
    """
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    """Return base + 1.5 * weight_kg, rounded to 2 decimals.

    Base is 5.0 for zone 1, 12.0 for zone 2 and 25.0 for zone 3.
    """
    base = _BASE_BY_ZONE[zone]
    return round(base + 1.5 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 120 or l + w + h exceeds 300."""
    return l > 120 or w > 120 or h > 120 or (l + w + h) > 300

